  el.querySelectorAll('[data-inspector-tab]').forEach(b=>b.onclick=()=>{inspectorTab=b.dataset.inspectorTab;renderInspector()});bindActions(el);el.querySelectorAll('[data-edit-event]').forEach(b=>b.onclick=()=>behaviorDialog(+b.dataset.editEvent));
  el.querySelectorAll('[data-prop]').forEach(input=>{input.disabled=playing;input.onchange=()=>{if(playing)return;const key=input.dataset.prop;let value=input.type==='checkbox'?input.checked:input.type==='number'?Number(input.value):input.value;if(input.type==='number'&&(!Number.isFinite(value)||Math.abs(value)>99999||(['w','h'].includes(key)&&value<=0)||(['bounce','friction'].includes(key)&&(value<0||value>1)))){notify('Enter a valid value.');renderInspector();return}record();if(o.lockAspect&&['w','h'].includes(key)){const ratio=o.w/o.h;if(key==='w')o.h=Math.max(1,Math.round(value/ratio));else o.w=Math.max(1,Math.round(value*ratio))}o[key]=value;changed()}});if($('#world-gravity'))$('#world-gravity').onchange=e=>{if(playing)return;if(e.target.value==='custom'){physicsDialog();return}record();project.gravity=+e.target.value;changed()}
