 function eventDescription(e){return e.action==='score'?`Add ${escape(e.value)} to Score`:e.action==='damage'?`Subtract ${escape(e.value)} from Health`:e.action==='loopmove'?`Move ${e.axis==='y'?(e.direction===1?'down':'up'):(e.direction===1?'right':'left')} · ${e.value} px/s · ${escape(e.movementMode||'wrap')}`:e.action==='shoot'?'Shoot a projectile':e.action==='toggle'?'Toggle object':e.action==='show'?'Show object':e.action==='hide'?'Hide object':e.action==='setgravity'?`Set gravity to ${e.value}×`:e.action==='finish'?'Finish level':e.action==='addvariable'?`Add ${e.value} to ${escape(e.variable||'Score')}`:e.action==='setvariable'?`Set ${escape(e.variable||'Score')} to ${e.value}`:e.action==='attach'?`Attach to ${escape(project.objects.find(o=>o.id===e.targetId)?.name||'object')}`:e.action==='facepointer'?'Face mouse / touch pointer':e.action==='moveplatform'?`Move ${escape(project.objects.find(o=>o.id===e.targetId)?.name||'platform')} (${e.axis?.toUpperCase()||'Y'}, ${e.value}px)`:e.action==='drag'?'Drag with mouse / touch':e.action==='sound'?`Play ${escape((project.sounds||[]).find(s=>s.id===e.soundId)?.name||'sound')}`:'Set checkpoint'}
 function behaviorDialog(index,presetAction){const o=selectedObject();if(!o){notify('Select an object first.');return}if(playing){notify('Stop the game before editing events.');return}const existing=o.events?.[index];showDialog(existing?'Edit visual event':'Quick Behavior Builder',`<form id="behavior-form"><label>Object<input readonly value="${escape(o.name)}"></label><label>Condition<select id="event-condition"><option value="touch">On Touch (Player)</option><option value="start">On Game Start</option><option value="pointerdown">On Pointer Down</option><option value="frame">Every Frame</option><option value="timer">On Timer</option><option value="input">On Input Pressed</option><option value="variable">When Variable Matches</option><option value="drop">On Drop into Object</option><option value="projectilehit">On Projectile Hit</option>${o.type==='gear'?'<option value="gearturn">On Gear Turn</option>':''}</select></label><label>Action<select id="event-action"><option value="score">Add to Score and collect</option><option value="damage">Subtract from Health and respawn</option><option value="checkpoint">Set checkpoint</option><option value="sound">Play sound</option><option value="drag">Drag with Mouse / Touch</option><option value="attach">Attach to Object</option><option value="facepointer">Face Mouse / Touch Pointer</option><option value="shoot">Shoot Projectile</option><option value="loopmove">Loop Movement</option><option value="toggle">Toggle Object</option><option value="show">Show Object</option><option value="hide">Hide Object</option><option value="setgravity">Set Gravity</option><option value="addvariable">Add to Variable</option><option value="setvariable">Set Variable</option><option value="finish">Finish Level</option>${o.type==='gear'?'<option value="moveplatform">Move Platform</option>':''}</select></label><label>Value<input id="event-value" type="number" required min="0" max="1000000" value="${existing?.value??1}"></label><div id="movement-event-fields"><label>Direction<select id="movement-direction"><option value="left">Right → Left</option><option value="right">Left → Right</option><option value="up">Bottom → Top</option><option value="down">Top → Bottom</option></select></label><label>Repeat<select id="movement-mode"><option value="wrap">Wrap and repeat forever</option><option value="pingpong">Back and forth</option><option value="once">Move once</option></select></label><label>Travel range (px)<input id="movement-range" type="number" min="1" max="4096" value="${existing?.range||200}"></label><div class="speed-presets"><button type="button" data-speed="60">Slow</button><button type="button" data-speed="140">Normal</button><button type="button" data-speed="240">Fast</button></div></div><div id="timer-event-fields"><label>Interval (seconds)<input id="event-interval" type="number" min="0.05" max="3600" step="0.05" value="${existing?.interval||1}"></label><label class="check"><input id="event-repeat" type="checkbox" ${existing?.repeat!==false?'checked':''}>Repeat</label></div><label id="input-event-fields">Input action<select id="event-input-action">${['shoot','jump','left','right','up','down'].map(key=>`<option value="${key}">${key}</option>`).join('')}</select></label><div id="variable-condition-fields"><label>Variable<input id="event-test-variable" value="${escape(existing?.testVariable||'Score')}" maxlength="40"></label><label>Comparison<select id="event-compare"><option value="atleast">At least</option><option value="eq">Equals</option><option value="below">Below</option></select></label><label>Threshold<input id="event-threshold" type="number" value="${existing?.threshold||0}"></label></div><label id="drop-condition-fields">Drop target<select id="event-drop-target">${project.objects.filter(p=>p.id!==o.id).map(p=>`<option value="${escape(p.id)}">${escape(p.name)}</option>`).join('')}</select></label><label id="event-consume-label" class="check"><input id="event-consume" type="checkbox" ${existing?.consume!==false?'checked':''}>Remove source after scoring</label><label id="event-target-label">Target object<select id="event-target">${project.objects.map(p=>`<option value="${escape(p.id)}">${escape(p.name)}</option>`).join('')}</select></label><label id="event-variable-label">Variable name<input id="event-variable" maxlength="40" value="${escape(existing?.variable||'Score')}"></label><label id="event-sound-label">Audio<select id="event-sound">${project.sounds.map(s=>`<option value="${escape(s.id)}">${escape(s.name)}</option>`).join('')}</select></label><div id="attach-fields"><label>Parent object<select id="attach-parent">${project.objects.filter(p=>p.id!==o.id).map(p=>`<option value="${escape(p.id)}">${escape(p.name)}</option>`).join('')}</select></label><div class="game-size-grid"><label>Offset X<input id="attach-offset-x" type="number" value="${existing?.offsetX||0}"></label><label>Offset Y<input id="attach-offset-y" type="number" value="${existing?.offsetY||0}"></label></div></div><div id="platform-link-fields"><label>Platform<select id="linked-platform">${project.objects.filter(p=>p.type==='platform').map(p=>`<option value="${escape(p.id)}">${escape(p.name)}</option>`).join('')}</select></label><label>Axis<select id="platform-axis"><option value="y">Vertical (Y)</option><option value="x">Horizontal (X)</option></select></label><label>Turn range (degrees)<input id="gear-turn-range" type="number" min="1" max="1440" value="${existing?.turnDegrees||180}"></label></div><button class="purple-button" type="submit">${existing?'Save event':'Add event'}</button></form>`);if(existing){$('#event-action').value=existing.action;$('#event-condition').value=existing.condition;$('#event-sound').value=existing.soundId||'';$('#linked-platform').value=existing.targetId||'';$('#platform-axis').value=existing.axis||'y';$('#attach-parent').value=existing.targetId||'';$('#event-target').value=existing.targetId||o.id;$('#event-input-action').value=existing.inputAction||'shoot';$('#event-compare').value=existing.compare||'atleast';$('#event-drop-target').value=existing.conditionTargetId||'';$('#movement-mode').value=existing.movementMode||'wrap';$('#movement-direction').value=existing.axis==='y'?(existing.direction===1?'down':'up'):(existing.direction===1?'right':'left');}if(presetAction)$('#event-action').value=presetAction;const refresh=()=>{const action=$('#event-action').value;$('#movement-event-fields').hidden=action!=='loopmove';if(action==='loopmove'){if($('#event-value').value==='1')$('#event-value').value=140;$('#event-condition').value='frame'}const condition=$('#event-condition').value;$('#timer-event-fields').hidden=condition!=='timer';$('#input-event-fields').hidden=condition!=='input';$('#variable-condition-fields').hidden=condition!=='variable';$('#drop-condition-fields').hidden=condition!=='drop';$('#event-consume-label').hidden=action!=='score';$('#event-target-label').hidden=!['toggle','show','hide'].includes(action);$('#event-variable-label').hidden=!['addvariable','setvariable'].includes(action);if(['toggle','show','hide'].includes(action)&&!$('#event-target').value)$('#event-target').value=o.id;const moving=action==='moveplatform';$('#attach-fields').hidden=action!=='attach';if(['attach','facepointer','loopmove'].includes(action)){$('#event-condition').value='frame';if(action==='attach'&&!$('#attach-parent').value&&$('#attach-parent').options.length)$('#attach-parent').selectedIndex=0;if(action==='facepointer'&&$('#event-value').value==='1')$('#event-value').value=0;}$('#platform-link-fields').hidden=!moving;$('#event-value').min=moving?-4096:['facepointer','setgravity','addvariable','setvariable'].includes(action)?-10000:0;if(moving){if(!$('#linked-platform').value&&$('#linked-platform').options.length)$('#linked-platform').selectedIndex=0;$('#event-condition').value='gearturn';if(!existing&&$('#event-value').value==='1')$('#event-value').value=-128}$('#event-sound-label').hidden=$('#event-action').value!=='sound';$('#event-value').closest('label').hidden=['sound','checkpoint','drag','attach','toggle','show','hide','finish'].includes($('#event-action').value)};$('#event-condition').onchange=refresh;$('#event-action').onchange=()=>{if($('#event-action').value==='shoot'){if(!existing)$('#event-condition').value='input';if($('#event-value').value==='1')$('#event-value').value=480}if($('#event-action').value==='drag')$('#event-condition').value='pointerdown';refresh()};refresh();$$('[data-speed]').forEach(b=>b.onclick=()=>$('#event-value').value=b.dataset.speed);$('#behavior-form').onsubmit=e=>{e.preventDefault();if($('#event-action').value==='sound'&&!$('#event-sound').value){notify('Create or import audio in Tools → Sound & SFX Editor first.');return}if($('#event-action').value==='moveplatform'&&!$('#linked-platform').value){notify('Add a platform before linking a gear.');return}if($('#event-action').value==='drag')$('#event-condition').value='pointerdown';if(['attach','facepointer','loopmove'].includes($('#event-action').value))$('#event-condition').value='frame';if($('#event-action').value==='attach'&&!$('#attach-parent').value){notify('Add another object to attach to.');return}if($('#event-action').value==='moveplatform')$('#event-condition').value='gearturn';if($('#event-action').value==='attach'){let ancestor=project.objects.find(p=>p.id===$('#attach-parent').value);for(let n=0;ancestor&&n<project.objects.length+1;n++){if(ancestor.id===o.id){notify('An object cannot attach to its own descendant.');return}const parentId=ancestor.events?.find(e=>e.action==='attach')?.targetId;ancestor=project.objects.find(p=>p.id===parentId)}}record();o.events??=[];const ev={id:existing?.id||crypto.randomUUID(),condition:$('#event-condition').value,action:$('#event-action').value,value:+$('#event-value').value};if(ev.action==='loopmove'){const direction=$('#movement-direction').value;ev.axis=['up','down'].includes(direction)?'y':'x';ev.direction=['right','down'].includes(direction)?1:-1;ev.movementMode=$('#movement-mode').value;ev.range=Math.max(1,+$('#movement-range').value||200)}if(ev.condition==='timer'){ev.interval=Math.max(.05,+$('#event-interval').value||1);ev.repeat=$('#event-repeat').checked}if(ev.condition==='input')ev.inputAction=$('#event-input-action').value;if(ev.condition==='variable'){ev.testVariable=$('#event-test-variable').value;ev.compare=$('#event-compare').value;ev.threshold=+$('#event-threshold').value||0}if(ev.condition==='drop')ev.conditionTargetId=$('#event-drop-target').value;if(ev.action==='score')ev.consume=$('#event-consume').checked;if(['toggle','show','hide'].includes(ev.action))ev.targetId=$('#event-target').value;if(['addvariable','setvariable'].includes(ev.action))ev.variable=$('#event-variable').value;if(ev.action==='shoot'&&!project.inputs)project.inputs={left:'ArrowLeft',right:'ArrowRight',up:'ArrowUp',down:'ArrowDown',jump:'Space',shoot:'Mouse0'};if(ev.action==='sound')ev.soundId=$('#event-sound').value;if(ev.action==='moveplatform'){ev.targetId=$('#linked-platform').value;ev.axis=$('#platform-axis').value;ev.turnDegrees=Math.max(1,Math.min(1440,+$('#gear-turn-range').value||180));ev.startAngle=o.rotation||0;}if(ev.action==='attach'){if(!existing)o.events=o.events.filter(event=>event.action!=='attach');ev.targetId=$('#attach-parent').value;ev.offsetX=Number($('#attach-offset-x').value)||0;ev.offsetY=Number($('#attach-offset-y').value)||0;o.physics=false;o.body='trigger'}if(existing)o.events[index]=ev;else o.events.push(ev);$('.editor-dialog').close();changed();addLog(`Visual event saved for ${o.name}.`)}}
 function renderWorkspace(){
  const el=$('#panel-workspace'),o=selectedObject();el.innerHTML=`<div class="workspace-tabs">${['Events','Variables','Input Mapper','Console','Debug'].map(t=>`<button data-bottom="${t}" class="${bottomTab===t?'active':''}">${t==='Events'?`Events${o?` (${escape(o.name)})`:''}`:t}${t==='Debug'&&diagnostics().length?' <i class="warning-dot"></i>':''}</button>`).join('')}</div><div class="workspace-content" id="workspace-content"></div>`;const content=$('#workspace-content');
  if(bottomTab==='Events'){content.innerHTML=o?`<div class="event-sheet">${(o.events||[]).map((e,i)=>`<div class="event-row"><span class="event-line">${i+1}</span><button class="event-condition" data-edit-event="${i}"><span>◉</span> ${e.condition==='timer'?'On Timer':e.condition==='input'?'On Input Pressed':e.condition==='variable'?'When Variable Matches':e.condition==='drop'?'On Drop into Object':e.condition==='projectilehit'?'On Projectile Hit':e.condition==='frame'?'Every Frame':e.condition==='gearturn'?'Gear Turn':e.condition==='pointerdown'?'Pointer Down':e.condition==='start'?'On Start':'On Touch'}</button><span class="event-target">${icon('cube',13)} Player</span><span>→</span><button class="event-action" data-edit-event="${i}">${eventDescription(e)}</button><button data-remove-event="${i}" aria-label="Delete event ${i+1}">${icon('trash',13)}</button></div>`).join('')||'<p class="panel-hint">No events for this object. Create a touch condition and choose what happens.</p>'}<button class="add-event" data-action="behavior">＋ Add Event</button></div>`:'<p class="panel-hint">Select an object to build its events.</p>';content.querySelectorAll('[data-edit-event]').forEach(b=>b.onclick=()=>behaviorDialog(+b.dataset.editEvent));content.querySelectorAll('[data-remove-event]').forEach(b=>b.onclick=()=>{if(playing)return;record();o.events.splice(+b.dataset.removeEvent,1);changed()})}
  if(bottomTab==='Variables'){content.innerHTML=`<div class="variable-table">${Object.entries(project.variables).map(([name,value])=>`<label><span>${escape(name)}</span><input type="number" data-variable="${escape(name)}" aria-label="Variable ${escape(name)}" value="${value}"></label>`).join('')}</div><button id="add-variable">＋ Add variable</button>`;content.querySelectorAll('[data-variable]').forEach(input=>input.onchange=()=>{if(playing)return;const v=+input.value;if(!Number.isFinite(v))return;record();project.variables[input.dataset.variable]=v;changed()});$('#add-variable').onclick=()=>{if(playing)return;const name=prompt('Variable name (letters, numbers and underscores)');if(!name)return;if(!/^[a-zA-Z][a-zA-Z0-9_]{0,39}$/.test(name)){notify('Use 1–40 letters, numbers or underscores.');return}if(Object.hasOwn(project.variables,name)){notify('That variable already exists.');return}record();project.variables[name]=0;changed()}}
  if(bottomTab==='Input Mapper')renderInputs(content);if(bottomTab==='Console')content.innerHTML=consoleRows();if(bottomTab==='Debug')renderDebug(content);
  if(bottomTab==='Events'){const legacy=document.createElement('details');legacy.className='legacy-events';legacy.innerHTML='<summary>Object behaviors (advanced)</summary>';while(content.firstChild)legacy.append(content.firstChild);const shared=document.createElement('div');shared.id='shared-rules';content.append(shared,legacy);mountRuleList(shared,project,{defaultObjectId:selected,beforeChange:record,onChange:changed,notify});if(playing)shared.querySelectorAll('button,input').forEach(input=>input.disabled=true)}
  el.querySelectorAll('[data-bottom]').forEach(b=>b.onclick=()=>{bottomTab=b.dataset.bottom;renderWorkspace()});bindActions(el)
 }
 function diagnostics(){const issues=[];if(!project.objects.some(o=>o.type==='player'))issues.push({message:'No player in this scene.',evidence:'Scene contains no Player object.',fix:'Add a player to make the scene playable.',type:'player'});for(const o of project.objects){if(o.type==='coin'&&!o.events?.some(e=>e.action==='score'))issues.push({message:`${o.name} has no collection event.`,evidence:`Coin at (${o.x}, ${o.y}) has no On Touch → Score action.`,fix:'Add On Touch (Player) → Add 1 to Score.',object:o.id,type:'coin'})}return issues}
 function renderDebug(el){const issues=diagnostics();el.innerHTML=`<div class="debug-heading">${icon('bolt',15)} Project checks <span>Local checks · no AI required</span><label class="orbit-footer">Orbit <input id="orbit-debug-toggle" type="checkbox" aria-label="Enable Orbit" ${orbitEnabled()?'checked':''}></label></div>${issues.length?issues.map((issue,i)=>`<div class="diagnostic"><b>⚠ ${escape(issue.message)}</b><p><strong>Evidence:</strong> ${escape(issue.evidence)}</p><p><strong>Proposed fix:</strong> ${escape(issue.fix)}</p><button data-fix="${i}" class="purple-button">Review fix</button></div>`).join(''):'<div class="debug-clear">✓ No issues detected by current project checks.</div>'}`;el.querySelectorAll('[data-fix]').forEach(b=>b.onclick=()=>reviewFix(issues[+b.dataset.fix]));if(playing){const watch=document.createElement('div');watch.id='runtime-watch';watch.className='runtime-watch';el.prepend(watch);updateWatch(performance.now(),true)}const toggle=el.querySelector('#orbit-debug-toggle');if(toggle)toggle.onchange=e=>{try{const prefs=JSON.parse(localStorage.getItem('playform.preferences')||'{}');prefs.ai=e.target.checked;localStorage.setItem('playform.preferences',JSON.stringify(prefs));document.querySelector('#ai').checked=prefs.ai;renderWorkspace();renderConsole()}catch{notify('Could not save Orbit preference.')}};renderOrbit(el)}
 function orbitEnabled(){try{return !!JSON.parse(localStorage.getItem('playform.preferences')||'{}').ai}catch{return false}}
 function renderOrbit(el){if(!orbitEnabled())return;const section=document.createElement('section');section.className='orbit-assist';section.innerHTML=`<strong>✧ Orbit</strong><p>Your game-making companion. Local guidance works without a model.</p>${project.description?`<p><b>Game brief:</b> ${escape(project.description)}</p>`:''}<div class="orbit-quick"><button data-guide="score">Make a collectible</button><button data-guide="gravity">Change gravity</button><button data-guide="layout">Change layout</button></div><div id="orbit-guidance"></div><form id="orbit-form"><label>Orbit mode<select id="orbit-mode"><option value="help">Explain / Debug</option><option value="build">Build project changes</option></select></label><label>Ask your connected AI model<input id="orbit-question" required maxlength="2000" placeholder="Why doesn’t my coin collect?"></label><button class="purple-button" id="ask-orbit" type="submit">Ask Orbit</button></form><p class="orbit-model-note">Desktop includes a local model. Website AI needs a connected model server.</p><div id="orbit-answer" aria-live="polite"></div>`;el.append(section);section.querySelectorAll('[data-guide]').forEach(b=>b.onclick=()=>{$('#orbit-guidance').textContent={score:'Select a coin → Quick Behavior Builder → On Touch (Player) → Add to Score and collect → Add event. Test with F5.',gravity:'Open World physics from Tools or the Project panel. Choose Earth, Moon, Mars, Zero Gravity, or a custom multiplier. Earth is 1.0×.',layout:'Open View → Customize layout. Move panels between docks, resize with dividers, or choose a preset. Your choices save on this device.'}[b.dataset.guide]});$('#orbit-form').onsubmit=async e=>{e.preventDefault();const answer=$('#orbit-answer'),button=$('#ask-orbit'),question=$('#orbit-question').value;button.disabled=true;answer.textContent='Orbit is checking the project…';try{const response=await fetch('/api/orbit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question,mode:$('#orbit-mode').value,project:{name:project.name,description:project.description||'',template:project.template,gravity:project.gravity,objects:project.objects.slice(0,40).map(o=>({name:o.name,type:o.type,x:o.x,y:o.y,events:o.events||[]})),issues:diagnostics()}})});const result=await response.json();if(!response.ok)throw Error(result.error||'Orbit could not connect.');answer.innerHTML=`<p><b>Suspected cause / goal:</b> ${escape(result.answer.suspectedCause)}</p><p><b>Evidence:</b> ${escape(result.answer.evidence)}</p><p><b>Proposed fix:</b> ${escape(result.answer.proposedFix)}</p><small>Orbit has not changed your project.</small>`;if(result.answer.proposals?.length){const button=document.createElement('button');button.className='purple-button';button.textContent='Review proposed changes';button.onclick=()=>reviewBuild(result.answer.proposals);answer.append(button)}}catch(error){answer.textContent=error.message}finally{button.disabled=false}}}
 function reviewBuild(proposals){try{const prepared=prepareProposal(project,proposals);showDialog('Review Orbit’s proposed changes',`${prepared.replacesScene?'<p><b>This replaces the current scene objects.</b> You can undo it after applying.</p>':''}<ul>${prepared.descriptions.map(d=>`<li>${escape(d)}</li>`).join('')}</ul><button id="apply-orbit-build" class="purple-button">Approve & apply changes</button>`);$('#apply-orbit-build').onclick=()=>{if(playing){notify('Stop the game before applying project changes.');return}record();Object.assign(project,prepared.candidate);selected=project.objects[0]?.id||null;$('.editor-dialog').close();changed();addLog('Approved Orbit project changes applied.','success')}}catch(error){notify(error.message)}}
 function reviewFix(issue){showDialog('Review project change',`<p><b>Suspected cause:</b> ${escape(issue.message)}</p><p><b>Evidence:</b> ${escape(issue.evidence)}</p><p><b>Proposed fix:</b> ${escape(issue.fix)}</p><button id="approve-fix" class="purple-button">Approve & apply fix</button>`);$('#approve-fix').onclick=()=>{if(playing){notify('Stop the game before applying a fix.');return}if(issue.type==='player')addObject('player');else{const o=project.objects.find(o=>o.id===issue.object);if(o){record();o.events??=[];o.events.push({id:crypto.randomUUID(),condition:'touch',action:'score',value:1});selected=o.id;changed();addLog(`Approved collection event added to ${o.name}.`,'success')}}$('.editor-dialog').close()}}
 function consoleRows(){return `<div class="console-rows">${log.map(row=>`<div class="log-row ${row.level}"><span>${row.level==='success'?'●':row.level==='warning'?'▲':'·'}</span><time>[${row.time}]</time> ${escape(row.message)}</div>`).join('')||'<p class="panel-hint">Console is clear.</p>'}</div>`}
 function renderConsole(){const el=$('#panel-console');if(!el)return;const issues=diagnostics();el.innerHTML=`<div class="console-toolbar"><span class="warning-count">▲ ${issues.length}</span><span class="error-count">⊗ 0</span><button id="clear-console">Clear</button><span class="toolbar-fill"></span><label class="orbit-footer">✧ Orbit <input id="orbit-toggle" type="checkbox" aria-label="Enable Orbit Assistant" ${orbitEnabled()?'checked':''}></label><button data-action="debug">${icon('bolt',13)} Debug</button></div>${consoleRows()}${issues[0]?`<button class="console-diagnostic" data-action="debug"><span>✧</span><span>${escape(issues[0].message)}<small>${escape(issues[0].fix)}</small></span><b>Review</b></button>`:''}`;$('#orbit-toggle').onchange=e=>{try{const prefs=JSON.parse(localStorage.getItem('playform.preferences')||'{}');prefs.ai=e.target.checked;localStorage.setItem('playform.preferences',JSON.stringify(prefs));const preference=document.querySelector('#ai');if(preference)preference.checked=prefs.ai;bottomTab='Debug';renderWorkspace()}catch{notify('Could not save Orbit preference.')}};$('#clear-console').onclick=()=>{log=[];renderConsole();if(bottomTab==='Console')renderWorkspace()};bindActions(el)}
 function updateCounts(){if(!$('#object-count'))return;$('#object-count').textContent=`Objects: ${project.objects.length}`;$('#event-count').textContent=`Events: ${project.objects.reduce((sum,o)=>sum+(o.events?.length||0),0)}`}
 function physicsDialog(){showDialog('World physics',`<p class="muted">Gravity is relative to Earth = 1.0×. Changes apply to the game preview.</p><label>Gravity preset<select id="physics-preset">${gravities.map(([n,g])=>`<option value="${g}" ${g===project.gravity?'selected':''}>${n}</option>`).join('')}<option value="custom">Custom</option></select></label><label>Gravity multiplier<input id="gravity-input" type="number" min="0" max="10" step="0.01" value="${project.gravity}"></label><button id="save-physics" class="purple-button">Apply physics</button>`);$('#physics-preset').onchange=e=>{if(e.target.value!=='custom')$('#gravity-input').value=e.target.value};$('#save-physics').onclick=()=>{const v=+$('#gravity-input').value;if(!Number.isFinite(v)||v<0||v>10){notify('Choose a gravity between 0 and 10×.');return}if(playing){notify('Stop the game before changing physics.');return}record();project.gravity=v;$('.editor-dialog').close();changed()}}
 function renderInputs(content){project.inputs??={left:'ArrowLeft',right:'ArrowRight',up:'ArrowUp',down:'ArrowDown',jump:'Space',shoot:'Space'};project.controller??={jump:0,shoot:1};content.innerHTML=`<div class="input-mapper">${Object.entries(project.inputs).map(([action,key])=>`<label><span>${escape(action[0].toUpperCase()+action.slice(1))}</span><input data-input-action="${action}" aria-label="Binding ${action}" value="${escape(key)}" readonly><select data-mouse-action="${action}" aria-label="Mouse binding ${action}"><option value="">Mouse…</option><option value="Mouse0">Left click</option><option value="Mouse2">Right click</option></select></label>`).join('')}<label><span>Controller jump</span><select data-controller="jump">${Array.from({length:16},(_,i)=>`<option value="${i}" ${project.controller.jump===i?'selected':''}>Button ${i}</option>`).join('')}</select></label><label><span>Controller shoot</span><select data-controller="shoot">${Array.from({length:16},(_,i)=>`<option value="${i}" ${project.controller.shoot===i?'selected':''}>Button ${i}</option>`).join('')}</select></label><button id="reset-inputs">Reset bindings</button></div>`;content.querySelectorAll('[data-input-action]').forEach(input=>{input.onfocus=()=>input.value='Press a key…';input.onblur=()=>input.value=project.inputs[input.dataset.inputAction];input.onkeydown=e=>{e.preventDefault();e.stopPropagation();if(playing)return;record();project.inputs[input.dataset.inputAction]=e.code;input.value=e.code;input.blur();persist()}});content.querySelectorAll('[data-mouse-action]').forEach(select=>select.onchange=()=>{if(!select.value||playing)return;record();project.inputs[select.dataset.mouseAction]=select.value;persist();renderWorkspace()});content.querySelectorAll('[data-controller]').forEach(select=>select.onchange=()=>{if(playing)return;record();project.controller[select.dataset.controller]=+select.value;persist()});$('#reset-inputs').onclick=()=>{if(playing)return;record();project.inputs={left:'ArrowLeft',right:'ArrowRight',up:'ArrowUp',down:'ArrowDown',jump:'Space',shoot:'Space'};project.controller={jump:0,shoot:1};persist();renderWorkspace()}}
 function editArt(kind){if(playing){notify('Stop the game before editing artwork.');return}openArtEditor({object:selectedObject(),project,initialMode:kind,notify,onChange:values=>{if(!selectedObject())addObject('player');record();Object.assign(selectedObject(),values);changed()}})}
 function inputPressed(action){const defaults={left:'ArrowLeft',right:'ArrowRight',up:'ArrowUp',down:'ArrowDown',jump:'Space',shoot:'Space'},aliases={left:'KeyA',right:'KeyD',up:'KeyW',down:'KeyS',jump:'ArrowUp'};if(keyState.has(project.inputs?.[action]||defaults[action])||runtime?.pendingKeys?.has(project.inputs?.[action]||defaults[action])||!project.inputs&&(keyState.has(aliases[action])||runtime?.pendingKeys?.has(aliases[action])))return true;const pad=navigator.getGamepads?.()?.[0];if(!pad)return false;return action==='left'?pad.axes[0]<-.3||pad.buttons[14]?.pressed:action==='right'?pad.axes[0]>.3||pad.buttons[15]?.pressed:action==='up'?pad.axes[1]<-.3||pad.buttons[12]?.pressed:action==='down'?pad.axes[1]>.3||pad.buttons[13]?.pressed:pad.buttons[project.controller?.[action]??(action==='jump'?0:1)]?.pressed}
 function editAudio(){if(playing){notify('Stop the game before editing audio.');return}openSoundEditor({project,notify,onChange:change=>{record();if(change.remove){project.sounds=project.sounds.filter(s=>s.id!==change.remove);for(const o of project.objects)o.events=(o.events||[]).filter(e=>e.soundId!==change.remove)}else{const index=project.sounds.findIndex(s=>s.id===change.sound.id);if(index>=0)project.sounds[index]=change.sound;else project.sounds.push(change.sound)}changed();renderAssets()}})}
 function startRoom(session){room?.leave();lastRoomMessage='';room=connectRoom(session,{onState:state=>{const oldRound=roomState?.round;roomState=state;if(oldRound!==undefined&&oldRound!==state.round&&playing)restartLocal();const b=$('#multiplayer-button');if(b)b.textContent=`Room ${state.code} · ${state.players.length}`;if(runtime){for(const o of runtime.objects){if(state.collected.includes(o.id))o.hidden=true}runtime.score=state.score;for(const update of state.objects||[]){const o=runtime.objects.find(o=>o.id===update.id);if(o&&playDrag?.o.id!==o.id){if(o.type==='gear'&&Number.isFinite(update.rotation))spinGear(runtime.objects,o,Number.isFinite(update.turnAngle)?update.turnAngle-(o.turnAngle??o.rotation??0):angleDelta(update.rotation*Math.PI/180,(o.rotation||0)*Math.PI/180)*180/Math.PI);Object.assign(o,update)}}}draw()},onError:message=>{if(message!==lastRoomMessage){lastRoomMessage=message;notify(message)}},onClosed:message=>{room=null;roomState=null;$('#multiplayer-button').textContent='Play with friends';notify(message)}});addLog(`Connected to multiplayer room ${session.code}.`,'success');if(!playing)togglePlay(true);}
 function multiplayerDialog(){if(room){showDialog('Play with friends',`<button id="copy-room-link" class="purple-button invite-button">Invite a friend</button><div class="room-players">${(roomState?.players||[]).map(p=>`<span style="color:${p.color}">● ${escape(p.name)}</span>`).join('')}</div><details class="room-options"><summary>Room code & options</summary><div class="room-code">${escape(room.session.code)}</div><button id="leave-room">Leave room</button></details>`);$('#copy-room-link').onclick=async()=>{const link=room.link();try{if(navigator.share)await navigator.share({title:project.name,text:'Play with me in Playform Studio',url:link});else{await navigator.clipboard.writeText(link);notify('Invite link copied. Send it to your friend.')}}catch(error){if(error.name!=='AbortError'){try{await navigator.clipboard.writeText(link);notify('Invite link copied.')}catch{notify(link)}}}};$('#leave-room').onclick=()=>{room.leave();room=null;roomState=null;$('#multiplayer-button').textContent='Play with friends';$('.editor-dialog').close();addLog('Left multiplayer room.')};return}showDialog('Play with friends',`<form id="room-form"><button id="host-room" type="submit" class="purple-button invite-button">Start multiplayer</button><details class="room-options"><summary>Player options</summary><label>Your name<input id="player-name" maxlength="24" value="${escape(localStorage.getItem('playform.player-name')||'Player')}"></label><label>Players<select id="room-capacity"><option>2</option><option selected>4</option><option>8</option></select></label></details></form><details class="room-options"><summary>Join using a code</summary><form id="join-room-form"><label>Room code<input id="room-code" maxlength="6" required placeholder="ABC123" autocapitalize="characters"></label><button id="join-room" type="submit">Join game</button></form></details>`);$('#room-form').onsubmit=async e=>{e.preventDefault();const button=$('#host-room');button.disabled=true;try{const name=$('#player-name').value||'Player';localStorage.setItem('playform.player-name',name);const session=await hostRoom(project,name,+$('#room-capacity').value);$('.editor-dialog').close();startRoom(session);multiplayerDialog()}catch(error){notify(error.message)}finally{button.disabled=false}};$('#join-room-form').onsubmit=async e=>{e.preventDefault();const button=$('#join-room');button.disabled=true;try{const session=await joinRoom($('#room-code').value,$('#player-name').value||'Player',project);$('.editor-dialog').close();onJoin(session)}catch(error){notify(error.message)}finally{button.disabled=false}}}
 function cameraDialog(){if(playing){notify('Stop the game before changing its camera.');return}let selectedPreset=project.camera?.mode||((project.gravity||0)===0?'topdown':'side');showDialog('Camera presets',`<div class="camera-preset-grid">${[['side','Side-scroller'],['topdown','Top-down'],['follow','Follow player'],['fixed','Fixed scene']].map(([id,label])=>`<button data-camera-preset="${id}" class="${selectedPreset===id?'active':''}">${label}</button>`).join('')}</div><form id="camera-form"><label>Follow target<select id="camera-target">${project.objects.filter(o=>o.type!=='trigger'&&o.type!=='camera').map(o=>`<option value="${escape(o.id)}">${escape(o.name)}</option>`).join('')}</select></label><label>Camera zoom<input id="camera-zoom" type="number" min="1" max="4" step="0.1" value="${project.camera?.zoom||1}"></label><label>Follow smoothing<input id="camera-smoothing" type="range" min="1" max="20" value="${project.camera?.smoothing||8}"></label><label class="check"><input type="checkbox" id="camera-match-physics" checked>Match movement and physics to the preset</label><button type="submit" class="purple-button">Apply camera</button></form>`);if(project.camera?.targetId)$('#camera-target').value=project.camera.targetId;$$('[data-camera-preset]').forEach(b=>b.onclick=()=>{selectedPreset=b.dataset.cameraPreset;$$('[data-camera-preset]').forEach(x=>x.classList.toggle('active',x===b));$('#camera-zoom').value=selectedPreset==='follow'?1.5:1});$('#camera-form').onsubmit=e=>{e.preventDefault();const cameraZoom=+$('#camera-zoom').value;if(!Number.isFinite(cameraZoom)||cameraZoom<1||cameraZoom>4){notify('Choose zoom between 1 and 4.');return}record();project.camera={mode:selectedPreset,zoom:cameraZoom,smoothing:+$('#camera-smoothing').value,targetId:$('#camera-target').value,useSceneCamera:false};if($('#camera-match-physics').checked){if(selectedPreset==='topdown'){project.gravity=0;if(project.autoRun)project.autoRun.enabled=false}else if(selectedPreset==='side')project.gravity=1}$('.editor-dialog').close();changed()}}
 function gameSize(){showDialog('Game size',`<div class="size-presets">${[['Desktop',1280,720],['HD',1920,1080],['Phone portrait',390,844],['Phone landscape',844,390],['Square',800,800],['Classic',960,540]].map(([name,w,h])=>`<button data-resolution="${w},${h}">${name}</button>`).join('')}</div><form id="game-size-form"><div class="game-size-grid"><label>Width (px)<input id="game-width" type="number" required min="160" max="4096" value="${project.width}"></label><label>Height (px)<input id="game-height" type="number" required min="160" max="4096" value="${project.height}"></label></div><label class="check"><input id="scale-scene" type="checkbox" checked>Scale existing objects to fit</label><button type="submit" class="purple-button">Apply size</button></form>`);$$('[data-resolution]').forEach(b=>b.onclick=()=>{const[w,h]=b.dataset.resolution.split(',');$('#game-width').value=w;$('#game-height').value=h});$('#game-size-form').onsubmit=e=>{e.preventDefault();if(playing){notify('Stop the game before resizing.');return}const w=+$('#game-width').value,h=+$('#game-height').value;if(![w,h].every(v=>Number.isInteger(v)&&v>=160&&v<=4096))return;record();if($('#scale-scene').checked)for(const o of project.objects){o.x=Math.round(o.x*w/project.width);o.y=Math.round(o.y*h/project.height);o.w=Math.max(1,Math.round(o.w*w/project.width));o.h=Math.max(1,Math.round(o.h*h/project.height))}project.width=w;project.height=h;zoom=1;pan={x:0,y:0};$('.editor-dialog').close();changed()}}
